ALTER TABLE "User" ADD COLUMN "emailVerifiedAt" TIMESTAMP(3), ADD COLUMN "locale" TEXT NOT NULL DEFAULT 'it';
UPDATE "User" SET "emailVerifiedAt"=CURRENT_TIMESTAMP;
ALTER TABLE "Session" ADD COLUMN IF NOT EXISTS "_migrationMarker" BOOLEAN; ALTER TABLE "Session" DROP COLUMN "_migrationMarker"; CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "Organization" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"legalType" TEXT NOT NULL DEFAULT 'BUSINESS',"plan" TEXT NOT NULL DEFAULT 'TRIAL',"locale" TEXT NOT NULL DEFAULT 'it',"trialEndsAt" TIMESTAMP(3),"readOnlyAt" TIMESTAMP(3),"deleteAfter" TIMESTAMP(3),"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Organization_slug_key" ON "Organization"("slug");
CREATE TABLE "OrganizationMember" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'MEMBER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OrganizationMember_pkey" PRIMARY KEY ("id"));
CREATE INDEX "OrganizationMember_userId_idx" ON "OrganizationMember"("userId"); CREATE UNIQUE INDEX "OrganizationMember_organizationId_userId_key" ON "OrganizationMember"("organizationId","userId");
INSERT INTO "Organization" ("id","name","slug","plan","locale","trialEndsAt","createdById","createdAt","updatedAt") SELECT 'org_'||"id","name","slug",'TRIAL','it',CURRENT_TIMESTAMP+INTERVAL '7 days',"createdById","createdAt",CURRENT_TIMESTAMP FROM "Workspace";
INSERT INTO "OrganizationMember" ("id","organizationId","userId","role","createdAt") SELECT 'orgmem_'||"id",'org_'||"workspaceId","userId","role","createdAt" FROM "WorkspaceMember";
ALTER TABLE "Workspace" ADD COLUMN "organizationId" TEXT, ADD COLUMN "presetKey" TEXT NOT NULL DEFAULT 'GENERAL', ADD COLUMN "locale" TEXT NOT NULL DEFAULT 'it', ADD COLUMN "revision" INTEGER NOT NULL DEFAULT 0;
UPDATE "Workspace" SET "organizationId"='org_'||"id", "transcriptionModel"='openai/whisper-large-v3-turbo'; ALTER TABLE "Workspace" ALTER COLUMN "organizationId" SET NOT NULL; CREATE INDEX "Workspace_organizationId_idx" ON "Workspace"("organizationId");
ALTER TABLE "BoardColumn" ADD COLUMN "description" TEXT NOT NULL DEFAULT '', ADD COLUMN "semanticKey" TEXT NOT NULL DEFAULT 'CUSTOM', ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
