CREATE UNIQUE INDEX "WorkspaceInvite_tokenHash_key" ON "WorkspaceInvite"("tokenHash"); CREATE INDEX "WorkspaceInvite_email_expiresAt_idx" ON "WorkspaceInvite"("email","expiresAt"); CREATE INDEX "WorkspaceInvite_organizationId_idx" ON "WorkspaceInvite"("organizationId");
CREATE TABLE "CardAssignee" ("cardId" TEXT NOT NULL,"userId" TEXT NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CardAssignee_pkey" PRIMARY KEY ("cardId","userId")); CREATE INDEX "CardAssignee_userId_idx" ON "CardAssignee"("userId");
CREATE TABLE "ActivityEvent" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"workspaceId" TEXT,"userId" TEXT NOT NULL,"type" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"batchId" TEXT,"beforeState" JSONB,"afterState" JSONB,"undoable" BOOLEAN NOT NULL DEFAULT false,"undoneAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ActivityEvent_pkey" PRIMARY KEY ("id")); CREATE INDEX "ActivityEvent_organizationId_createdAt_idx" ON "ActivityEvent"("organizationId","createdAt"); CREATE INDEX "ActivityEvent_workspaceId_createdAt_idx" ON "ActivityEvent"("workspaceId","createdAt"); CREATE INDEX "ActivityEvent_batchId_idx" ON "ActivityEvent"("batchId");
CREATE TABLE "UsageEvent" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"workspaceId" TEXT,"userId" TEXT,"providerRequestId" TEXT,"category" TEXT NOT NULL,"model" TEXT NOT NULL,"costUsd" DOUBLE PRECISION NOT NULL,"periodKey" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "UsageEvent_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "UsageEvent_providerRequestId_key" ON "UsageEvent"("providerRequestId"); CREATE INDEX "UsageEvent_organizationId_periodKey_idx" ON "UsageEvent"("organizationId","periodKey");
CREATE TABLE "Subscription" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"stripeCustomerId" TEXT,"stripeSubscriptionId" TEXT,"stripePriceId" TEXT,"status" TEXT NOT NULL DEFAULT 'trialing',"currentPeriodEnd" TIMESTAMP(3),"cancelAtPeriodEnd" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Subscription_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Subscription_organizationId_key" ON "Subscription"("organizationId"); CREATE UNIQUE INDEX "Subscription_stripeCustomerId_key" ON "Subscription"("stripeCustomerId"); CREATE UNIQUE INDEX "Subscription_stripeSubscriptionId_key" ON "Subscription"("stripeSubscriptionId");
CREATE TABLE "BillingWebhook" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"type" TEXT NOT NULL,"processedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "BillingWebhook_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "BillingWebhook_eventId_key" ON "BillingWebhook"("eventId");
CREATE TABLE "VerificationToken" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "VerificationToken_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "VerificationToken_tokenHash_key" ON "VerificationToken"("tokenHash"); CREATE INDEX "VerificationToken_userId_expiresAt_idx" ON "VerificationToken"("userId","expiresAt");
CREATE TABLE "PasswordResetToken" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PasswordResetToken_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "PasswordResetToken_tokenHash_key" ON "PasswordResetToken"("tokenHash"); CREATE INDEX "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId","expiresAt");
